//! Embedded SteamStub loader DLLs, one per architecture, for gbe_fork's `load_dlls` folder.
//!
//! gbe_fork loads every DLL it finds in `steam_settings\load_dlls\` into the game process. Drydock
//! used to drop the two generic Steamworks stubs (`steam_stubbed.dll` + `stub.dll`) there; it now
//! drops the single SteamStub loader matching the game's bitness instead, which is what unwraps
//! SteamStub-protected executables.
//!
//! Stored gzip+base64 as source text so no standalone `.dll` sits in the repo for antivirus to
//! delete. Decoded on demand by [`load_dll_stub`]. To regenerate if a loader ever changes, gzip the
//! DLL and base64-encode it into the matching const below.

use std::io::Read;

use base64::Engine;

use crate::emu_template::PeArch;

const STEAMSTUB_X64_GZ_B64: &str = "";
const STEAMSTUB_X86_GZ_B64: &str = "";

fn inflate(b64: &str) -> Vec<u8> {
    let compressed = base64::engine::general_purpose::STANDARD
        .decode(b64)
        .expect("embedded load_dll base64");
    let mut out = Vec::new();
    flate2::read::GzDecoder::new(std::io::Cursor::new(compressed))
        .read_to_end(&mut out)
        .expect("embedded load_dll gzip");
    out
}

/// The SteamStub loader for `arch` as `(file name, bytes)`, decoded from the embedded blob. The file
/// keeps its upstream name so a deployed crack folder stays recognisable.
#[must_use]
pub fn load_dll_stub(arch: PeArch) -> (&'static str, Vec<u8>) {
    match arch {
        PeArch::X64 => ("steamstub_x64.dll", inflate(STEAMSTUB_X64_GZ_B64)),
        PeArch::X86 => ("steamstub_x32.dll", inflate(STEAMSTUB_X86_GZ_B64)),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::emu_template::detect_pe_arch;

    #[test]
    fn each_architecture_decodes_to_a_matching_pe() {
        for (arch, expected_name, expected_len) in [
            (PeArch::X64, "steamstub_x64.dll", 300_544),
            (PeArch::X86, "steamstub_x32.dll", 240_640),
        ] {
            let (name, bytes) = load_dll_stub(arch);
            assert_eq!(name, expected_name);
            assert_eq!(bytes.len(), expected_len, "{name} decoded to the wrong size");
            assert_eq!(
                detect_pe_arch(&bytes),
                Some(arch),
                "{name} is not a {} PE",
                arch.folder()
            );
        }
    }
}
